mapper.select:
SELECT EDV.シリアルナンバー AS serialNo, '' AS staffName, EDV.貸出開始日 AS startDate, EDV.返却予定日 AS limitDate, EDV.最終所在確認日 AS confirmedDate, EDV.備考 AS totalCount, EDV.stock_type, EDV.stock_code, EDV.備品データID AS stockDataId, EDV.社員番号 AS staff_no FROM equip_detail_view EDV WHERE 1 = 1 AND EDV.stock_type = #{type} AND EDV.stock_code = #{code}
/* [在庫]データの取得 */ AND EDV.社員番号 IS NULL AND (DATEDIFF(CURRENT_DATE(), EDV.最終所在確認日 ) <= 365 )
ORDER BY EDV.シリアルナンバー
